import React, { useState, useRef, useCallback } from "react";

const STATUS = { idle: "idle", uploading: "uploading", processing: "processing", done: "done", error: "error" };

export default function VideoUpload({ onVideoStart, onVideoStop }) {
  const [status,   setStatus]   = useState(STATUS.idle);
  const [progress, setProgress] = useState(0);
  const [fileName, setFileName] = useState(null);
  const [errorMsg, setErrorMsg] = useState(null);
  const [dragging, setDragging] = useState(false);
  const inputRef = useRef(null);

  const reset = () => {
    setStatus(STATUS.idle);
    setProgress(0);
    setFileName(null);
    setErrorMsg(null);
    onVideoStop?.();
  };

  const uploadFile = useCallback(async (file) => {
    if (!file) return;

    const allowed = ["video/mp4", "video/avi", "video/x-msvideo", "video/quicktime",
                     "video/x-matroska", "video/webm", "video/mpeg"];
    if (!allowed.includes(file.type) && !file.name.match(/\.(mp4|avi|mov|mkv|webm|mpeg|mpg)$/i)) {
      setErrorMsg("Unsupported format. Use MP4, AVI, MOV, MKV, or WebM.");
      setStatus(STATUS.error);
      return;
    }

    setFileName(file.name);
    setStatus(STATUS.uploading);
    setProgress(0);
    setErrorMsg(null);

    const formData = new FormData();
    formData.append("video", file);

    try {
      const xhr = new XMLHttpRequest();

      xhr.upload.onprogress = (e) => {
        if (e.lengthComputable) {
          setProgress(Math.round((e.loaded / e.total) * 100));
        }
      };

      xhr.onload = () => {
        if (xhr.status === 200) {
          const res = JSON.parse(xhr.responseText);
          setStatus(STATUS.processing);
          onVideoStart?.(res.filename);
        } else {
          const res = JSON.parse(xhr.responseText);
          setErrorMsg(res.error || "Upload failed");
          setStatus(STATUS.error);
        }
      };

      xhr.onerror = () => {
        setErrorMsg("Network error — is the backend running on port 3001?");
        setStatus(STATUS.error);
      };

      xhr.open("POST", "http://localhost:3001/upload-video");
      xhr.send(formData);

    } catch (err) {
      setErrorMsg(err.message);
      setStatus(STATUS.error);
    }
  }, [onVideoStart, onVideoStop]);

  // Drag handlers
  const onDragOver  = (e) => { e.preventDefault(); setDragging(true); };
  const onDragLeave = ()  => setDragging(false);
  const onDrop      = (e) => {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) uploadFile(file);
  };
  const onFileChange = (e) => {
    const file = e.target.files[0];
    if (file) uploadFile(file);
  };

  const card = {
    background: "#1a1d27", borderRadius: 12,
    border: "1px solid #2a2d3a", overflow: "hidden", marginBottom: 16,
  };
  const dropZone = {
    margin: 16,
    border: `2px dashed ${dragging ? "#3b5bdb" : "#2a2d3a"}`,
    borderRadius: 10,
    padding: "28px 20px",
    textAlign: "center",
    cursor: "pointer",
    transition: "border-color .2s, background .2s",
    background: dragging ? "rgba(59,91,219,0.06)" : "transparent",
  };

  return (
    <div style={card}>
      <div style={{ padding: "12px 16px", borderBottom: "1px solid #2a2d3a",
                    display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 13, fontWeight: 600, color: "#9ca3af", letterSpacing: 0.5 }}>
          VIDEO FILE INPUT
        </span>
        {(status === STATUS.processing || status === STATUS.done) && (
          <button onClick={reset} style={{
            fontSize: 12, color: "#6b7280", background: "none",
            border: "0.5px solid #2a2d3a", borderRadius: 6,
            padding: "3px 10px", cursor: "pointer",
          }}>
            ✕ Clear
          </button>
        )}
      </div>

      {/* IDLE / ERROR — show drop zone */}
      {(status === STATUS.idle || status === STATUS.error) && (
        <div
          style={dropZone}
          onDragOver={onDragOver}
          onDragLeave={onDragLeave}
          onDrop={onDrop}
          onClick={() => inputRef.current?.click()}
        >
          <input
            ref={inputRef}
            type="file"
            accept="video/mp4,video/avi,video/quicktime,video/x-matroska,video/webm,.mp4,.avi,.mov,.mkv,.webm"
            style={{ display: "none" }}
            onChange={onFileChange}
          />
          <div style={{ fontSize: 28, marginBottom: 10, color: "#4b5563" }}>⬆</div>
          <div style={{ fontSize: 14, color: "#9ca3af", marginBottom: 6 }}>
            Drag & drop a video file here
          </div>
          <div style={{ fontSize: 12, color: "#6b7280", marginBottom: 14 }}>
            MP4, AVI, MOV, MKV, WebM supported
          </div>
          <button style={{
            padding: "7px 20px", background: "#3b5bdb", color: "#fff",
            border: "none", borderRadius: 8, fontSize: 13,
            fontWeight: 600, cursor: "pointer",
          }}>
            Browse file
          </button>
          {status === STATUS.error && errorMsg && (
            <div style={{ marginTop: 12, fontSize: 12, color: "#ef4444" }}>
              {errorMsg}
            </div>
          )}
        </div>
      )}

      {/* UPLOADING */}
      {status === STATUS.uploading && (
        <div style={{ padding: 20 }}>
          <div style={{ fontSize: 13, color: "#9ca3af", marginBottom: 10 }}>
            Uploading <strong style={{ color: "#e8e6df" }}>{fileName}</strong>...
          </div>
          <div style={{ height: 6, background: "#2a2d3a", borderRadius: 3, overflow: "hidden" }}>
            <div style={{
              width: `${progress}%`, height: "100%",
              background: "#3b5bdb", borderRadius: 3,
              transition: "width .2s",
            }} />
          </div>
          <div style={{ fontSize: 12, color: "#6b7280", marginTop: 6, textAlign: "right" }}>
            {progress}%
          </div>
        </div>
      )}

      {/* PROCESSING */}
      {status === STATUS.processing && (
        <div style={{ padding: 20 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
            <Spinner />
            <div>
              <div style={{ fontSize: 13, color: "#9ca3af" }}>
                Processing <strong style={{ color: "#e8e6df" }}>{fileName}</strong>
              </div>
              <div style={{ fontSize: 11, color: "#6b7280", marginTop: 2 }}>
                Detection engine is scanning the video — alerts appear in real time
              </div>
            </div>
          </div>
          <div style={{ height: 4, background: "#2a2d3a", borderRadius: 2, overflow: "hidden" }}>
            <div style={{
              height: "100%", background: "#22c55e", borderRadius: 2,
              animation: "indeterminate 1.4s ease infinite",
            }} />
          </div>
          <style>{`
            @keyframes indeterminate {
              0%   { width: 0%;   margin-left: 0; }
              50%  { width: 60%;  margin-left: 20%; }
              100% { width: 0%;   margin-left: 100%; }
            }
          `}</style>
        </div>
      )}
    </div>
  );
}

function Spinner() {
  return (
    <div style={{
      width: 18, height: 18, borderRadius: "50%",
      border: "2px solid #2a2d3a",
      borderTopColor: "#22c55e",
      flexShrink: 0,
      animation: "spin .7s linear infinite",
    }}>
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}
